UPDATE tb_itinerary_comment
SET status = 'DELETED'
WHERE
comment_id = #{commentId}
AND itinerary_id = #{itineraryId}
AND user_id
= #{userId}
AND status = 'ACTIVE'

UPDATE tb_itinerary_comment
SET content = #{content},
updated_at = CURRENT_TIMESTAMP
WHERE comment_id = #{commentId}
AND itinerary_id = #{itineraryId}
AND user_id = #{userId}
AND status = 'ACTIVE'
